const pos=new T.Vector3(p.x,terrainHeight(p.x,p.y),p.y),moved=pos.distanceTo(model.previous);model.previous.copy(pos);model.root.position.copy(pos);const angle=Math.atan2(-p.face.x,-p.face.y);let diff=((angle-model.body.rotation.y+Math.PI)%(TAU)+TAU)%TAU-Math.PI;model.body.rotation.y+=diff*Math.min(1,dt*14);if(!state.paused)model.walk+=Math.min(moved,8)*.23;const walking=p.active&&p.frozen<=state.now&&moved>.015&&!state.paused;const stride=walking?Math.sin(model.walk)*.48:Math.sin(this.time*1.5)*.015;for(const [k,j]of Object.entries(model.joints)){if(k==='leftLeg')j.rotation.x=stride;if(k==='rightLeg')j.rotation.x=-stride;if(k==='leftArm')j.rotation.x=-stride*.65;if(k==='rightArm')j.rotation.x=stride*.65;if(k==='cape')j.rotation.x=.1+Math.sin(this.time*2)*.05+(walking?.12:0);if(k==='orb')j.position.y=-4.6+Math.sin(this.time*2)*.35}model.body.position.y=walking?Math.abs(Math.sin(model.walk))*.55:Math.sin(this.time*2)*.07;model.tails.forEach((t,i)=>{t.rotation.x=Math.sin(this.time*1.8+i*.3)*.06;t.rotation.z=Math.sin(this.time*1.4+i*.5)*.07});if(p.cd.a>state.now&&model.joints.rightArm)model.joints.rightArm.rotation.x=-1.7+Math.sin((p.cd.a-state.now)*Math.PI)*1.2;
model.select.material.color.set(p.id===0?'#e6d494':p.role==='hider'?'#77cdbc':'#e79777');model.select.material.opacity=p.id===0?.85:.55;model.shield.visible=p.immune>state.now;model.shield.rotation.y=this.time;model.freeze.visible=p.frozen>state.now;model.freeze.rotation.y=this.time*.2;model.root.scale.setScalar(p.recalling>state.now?Math.max(.15,(p.recalling-state.now)/2):1);if(p.hidden>state.now||p.hero==='Teemo'&&state.now-p.lastMove>2){model.select.material.opacity=.3;model.shield.visible=true;model.shield.material.opacity=.08}else model.shield.material.opacity=.15;
