drawMinimap(s){const c=this.miniCtx;if(!c)return;c.clearRect(0,0,360,360);c.fillStyle='#0d241b';c.fillRect(0,0,360,360);if(this.config.map.complete&&this.config.map.naturalWidth){c.globalAlpha=.85;c.drawImage(this.config.map,0,0,360,360);c.globalAlpha=1}c.fillStyle='#05141070';c.beginPath();c.moveTo(0,0);c.lineTo(360,0);c.lineTo(360,18);c.lineTo(18,360);c.lineTo(0,360);c.fill();this.post.drawMinimap(c,360);const me=s.players[0];for(const p of s.players){if(!p.active||!s.visible(me,p))continue;c.fillStyle=p.id===0?'#ffe5a1':p.role==='hider'?'#76d4bb':'#f18a74';c.beginPath();c.arc(p.x*.36,p.y*.36,p.id===0?5.5:4,0,TAU);c.fill()}c.strokeStyle='#efdf9c';c.lineWidth=1.4;const size=this.distance*.19;c.strokeRect(this.focus.x*.36-size/2,this.focus.z*.36-size/2,size,size);}
